SOURCES = {'mediaengine': '# SPDX-License-Identifier: GPL-3.0-or-later\n\n"""The playback engine of one media viewer: a GstPlay and its video sink.\n\nGstPlay is freed unsafely right after ``stop()``: its internal thread can\nstill be building a message when the last reference goes\n(``gst_message_new_custom`` -> SIGSEGV in\n``g_type_check_instance_is_fundamentally_a``, about 1 in 100 open/close\ncycles). So an :class:`Engine` is never dropped directly:\n\n* ``release()`` stops the pipeline, waits for the adapter to report\n  ``STOPPED``, disconnects every handler and drops the references from an\n  idle callback;\n* until then the engine sits in ``_releasing``, so it outlives the viewer\n  that closed it;\n* at quit :func:`shutdown_all` does the same synchronously, turning the\n  main context until ``STOPPED``, because the interpreter would otherwise\n  free a playing GstPlay during teardown.\n\nHandlers are connected once, in ``__init__``, and their ids are kept so\nthat release can undo every one of them. Events reach the owner by a\nmethod call, ``owner._engine_event(name, *args)``; a closure that\ncaptured the owner would leak it (see MEMORY-LEAKS.md).\n\nThis module imports only Gst, GstPlay, GstPbutils, GLib and Gtk.\n"""\n\nimport gc\nimport time\n\nimport gi\n\ngi.require_version(\'Gtk\', \'4.0\')\ngi.require_version(\'Gst\', \'1.0\')\ngi.require_version(\'GstPlay\', \'1.0\')\ngi.require_version(\'GstPbutils\', \'1.0\')\n\nfrom gi.repository import GLib, Gst, GstPbutils, GstPlay, Gtk  # noqa: E402,F401\n\n# How long release waits for STOPPED before dropping the engine anyway.\nSTOP_TIMEOUT_MS = 1000\n\n# Engines that were asked to release and have not been dropped yet. A\n# strong reference: the engine must outlive the viewer that closed it.\n_releasing = set()\n# Every engine not yet dropped, for shutdown_all().\n_all = set()\n\n\nclass Engine:\n    """One GstPlay with its ``gtk4paintablesink``, owned by one viewer.\n\n    ``owner`` gets ``_engine_event(name, *args)`` for: ``state-changed``\n    (a ``GstPlay.PlayState``), ``position`` / ``duration`` (nanoseconds),\n    ``media-info`` (a ``PlayMediaInfo``), ``seek-done`` (position),\n    ``end-of-stream``, ``error`` (a ``GLib.Error``), ``missing-plugin``\n    (description, installer detail), ``frame`` and ``size``.\n    """\n\n    def __init__(self, owner=None):\n        Gst.init(None)\n        sink = Gst.ElementFactory.make(\'gtk4paintablesink\')\n        if sink is None:\n            raise RuntimeError(\'gtk4paintablesink is not available\')\n        self.owner = owner\n        self.sink = sink\n        self.paintable = sink.props.paintable\n        outer = sink\n        if self.paintable.props.gl_context:\n            gl_sink = Gst.ElementFactory.make(\'glsinkbin\')\n            if gl_sink is not None:\n                gl_sink.props.sink = sink\n                outer = gl_sink\n        self.play = GstPlay.Play(\n            video_renderer=GstPlay.PlayVideoOverlayVideoRenderer.new_with_sink(\n                None, outer))\n        self.adapter = GstPlay.PlaySignalAdapter.new(self.play)\n        self.uri = None\n        self.state = GstPlay.PlayState.STOPPED\n        self.released = False\n        self._loaded = False\n        self._finished = False\n        self._timeout = 0\n        self._bus = None\n        self._handlers = []\n        _all.add(self)\n\n        self._connect(self.adapter, \'state-changed\', self._on_state)\n        self._connect(self.adapter, \'position-updated\', self._on_position)\n        self._connect(self.adapter, \'duration-changed\', self._on_duration)\n        self._connect(self.adapter, \'media-info-updated\', self._on_media_info)\n        self._connect(self.adapter, \'seek-done\', self._on_seek_done)\n        self._connect(self.adapter, \'end-of-stream\', self._on_end)\n        self._connect(self.adapter, \'error\', self._on_error)\n        self._connect(self.paintable, \'invalidate-contents\', self._on_frame)\n        self._connect(self.paintable, \'invalidate-size\', self._on_size)\n        bus = self.play.get_pipeline().get_bus()\n        if bus is not None:\n            bus.add_signal_watch()\n            self._bus = bus\n            self._connect(bus, \'message\', self._on_bus_message)\n\n    def _connect(self, obj, signal, callback):\n        self._handlers.append((obj, obj.connect(signal, callback)))\n\n    def _disconnect_all(self):\n        handlers, self._handlers = self._handlers, []\n        for obj, handler_id in handlers:\n            try:\n                obj.disconnect(handler_id)\n            except (TypeError, RuntimeError):\n                pass\n        if self._bus is not None:\n            self._bus.remove_signal_watch()\n            self._bus = None\n\n    def _emit(self, name, *args):\n        owner = self.owner\n        if owner is not None:\n            owner._engine_event(name, *args)\n\n    # Handlers: each only relays, so none holds the owner.\n\n    def _on_state(self, _adapter, state):\n        self.state = state\n        if self.released and state == GstPlay.PlayState.STOPPED:\n            self._finish()\n            return\n        self._emit(\'state-changed\', state)\n\n    def _on_position(self, _adapter, position):\n        self._emit(\'position\', position)\n\n    def _on_duration(self, _adapter, duration):\n        self._emit(\'duration\', duration)\n\n    def _on_media_info(self, _adapter, info):\n        self._emit(\'media-info\', info)\n\n    def _on_seek_done(self, _adapter, position):\n        self._emit(\'seek-done\', position)\n\n    def _on_end(self, _adapter):\n        self._emit(\'end-of-stream\')\n\n    def _on_error(self, _adapter, error, _details):\n        self._emit(\'error\', error)\n\n    def _on_frame(self, _paintable):\n        self._emit(\'frame\')\n\n    def _on_size(self, _paintable):\n        self._emit(\'size\')\n\n    def _on_bus_message(self, _bus, message):\n        if GstPbutils.is_missing_plugin_message(message):\n            self._emit(\n                \'missing-plugin\',\n                GstPbutils.missing_plugin_message_get_description(message),\n                GstPbutils.missing_plugin_message_get_installer_detail(\n                    message))\n\n    # Control\n\n    @property\n    def active(self):\n        return not self.released and self.play is not None\n\n    def load(self, uri):\n        """Prepare *uri* and preroll it: ``pause()`` after ``set_uri``,\n        because the stream only becomes prepared from the preroll."""\n        if not self.active:\n            return\n        self.uri = uri\n        self._loaded = True\n        self.play.set_uri(uri)\n        self.play.pause()\n\n    def start(self):\n        if self.active:\n            self.play.play()\n\n    def pause(self):\n        if self.active:\n            self.play.pause()\n\n    def seek(self, position_ns):\n        if self.active:\n            self.play.seek(position_ns)\n\n    def set_audio(self, muted, volume):\n        if self.active:\n            self.play.set_mute(muted)\n            self.play.set_volume(volume)\n\n    def stop(self):\n        """Stop the pipeline but keep the engine, for the next ``load``."""\n        if self.active:\n            self.owner = None\n            self._loaded = False\n            self.play.stop()\n\n    # Deferred release\n\n    def release(self):\n        """Stop, wait for STOPPED, disconnect, and drop the references\n        from an idle callback. Safe to call twice."""\n        if self.released:\n            return\n        self.released = True\n        self.owner = None\n        _releasing.add(self)\n        if self.state == GstPlay.PlayState.STOPPED and not self._loaded:\n            # Never started: nothing will report STOPPED.\n            self._finish()\n            return\n        self._timeout = GLib.timeout_add(STOP_TIMEOUT_MS, self._on_timeout)\n        self.play.stop()\n\n    def _on_timeout(self):\n        self._timeout = 0\n        self._finish()\n        return False\n\n    def _finish(self, immediate=False):\n        if self._finished:\n            return\n        self._finished = True\n        if self._timeout:\n            GLib.source_remove(self._timeout)\n            self._timeout = 0\n        self._disconnect_all()\n        if immediate:\n            self._drop()\n        else:\n            GLib.idle_add(self._drop_idle)\n\n    def _drop_idle(self):\n        self._drop()\n        return False\n\n    def _drop(self):\n        self.play = self.adapter = self.sink = self.paintable = None\n        _releasing.discard(self)\n        _all.discard(self)\n\n\ndef shutdown_all(timeout_s=1.0):\n    """Stop every engine and wait (bounded) for STOPPED, turning the main\n    context so the adapter can report it, then drop them all. Called from\n    ``do_shutdown``: a playing GstPlay freed by interpreter teardown\n    crashed 17 quits in 50."""\n    engines = [e for e in _all if e.play is not None]\n    for engine in engines:\n        engine.released = True\n        engine.owner = None\n        if engine.state != GstPlay.PlayState.STOPPED or engine._loaded:\n            engine.play.stop()\n    context = GLib.MainContext.default()\n    deadline = time.monotonic() + timeout_s\n    while time.monotonic() < deadline:\n        # An engine whose state is STOPPED finished itself in _on_state;\n        # one that never loaded is already STOPPED.\n        pending = [e for e in engines\n                   if not e._finished\n                   and (e.state != GstPlay.PlayState.STOPPED or e._loaded)]\n        if not pending:\n            break\n        if not context.iteration(False):\n            time.sleep(0.002)\n    for engine in engines:\n        engine._finish(immediate=True)\n        engine._drop()\n    gc.collect()\n', 'mediastream': '# SPDX-License-Identifier: GPL-3.0-or-later\n\n"""A ``Gtk.MediaStream`` that plays through a :class:`mediaengine.Engine`.\n\n``Gtk.Video``, ``Gtk.MediaControls`` and a ``Gtk.Picture`` showing a GIFV\nall take a ``Gtk.MediaStream``. This one forwards play, pause, seek and\naudio to the engine\'s GstPlay and draws the engine\'s\n``gtk4paintablesink`` paintable, so the widgets stay as they were.\n\n* **Prepared from the preroll**, not from the duration: ``load()``\n  prerolls, and the first media info says which streams exist and\n  whether the source is seekable.\n* **No seek on a source that cannot seek**: GstPlay would error out\n  ("Could not seek in resource"), so ``do_seek`` calls ``seek_failed()``\n  and never reaches the engine.\n* **After ``detach()`` every vfunc is a no-op**, so a widget that still\n  holds the stream cannot reach a GstPlay that is being released.\n"""\n\nimport gi\n\ngi.require_version(\'Gtk\', \'4.0\')\ngi.require_version(\'GstPlay\', \'1.0\')\n\nfrom .i18n import gettext as _  # noqa: E402\n\nfrom gi.repository import Gio, GLib, Gtk  # noqa: E402\n\n# A seek that never reports completion is given up on after this long.\nSEEK_FALLBACK_MS = 2000\n\n_CODECS_EXTRA_MARKERS = (\'h264\', \'h.264\', \'avc\', \'hevc\', \'h265\', \'h.265\')\n\n\ndef missing_plugin_message(description, detail):\n    """The user-facing text for a missing codec. H.264 and HEVC need the\n    ``codecs-extra`` extension of the Flatpak runtime."""\n    text = (\'%s %s\' % (description or \'\', detail or \'\')).lower()\n    if any(marker in text for marker in _CODECS_EXTRA_MARKERS):\n        # Translators: shown when a video cannot be played because the\n        # system lacks its decoder. "codecs-extra" is the name of the\n        # Flatpak extension and is not translated.\n        return _(\'This video uses a format that needs the codecs-extra \'\n                 \'extension. Install it and try again.\')\n    # Translators: {codec} is the name of the missing decoder, as GStreamer\n    # words it, for example "Vorbis audio decoder".\n    return _(\'This media needs a codec that is not installed: {codec}\').format(\n        codec=description or \'?\')\n\n\nclass EngineStream(Gtk.MediaStream):\n    __gtype_name__ = \'BabbleEngineStream\'\n\n    def __init__(self, engine):\n        super().__init__()\n        self.engine = engine\n        self._seekable = False\n        self._seeking = False\n        self._seek_timeout = 0\n        self._at_end = False\n        self._duration_us = 0\n        self._failed = False\n        engine.owner = self\n\n    # Lifetime\n\n    def detach(self):\n        """Let go of the engine. The owner of the engine releases it."""\n        engine, self.engine = self.engine, None\n        if self._seek_timeout:\n            GLib.source_remove(self._seek_timeout)\n            self._seek_timeout = 0\n        if engine is not None and engine.owner is self:\n            engine.owner = None\n\n    # Events from the engine\n\n    def _engine_event(self, name, *args):\n        if self.engine is None:\n            return\n        getattr(self, \'_on_\' + name.replace(\'-\', \'_\'))(*args)\n\n    def _on_media_info(self, info):\n        # A stale message from the media loaded before this one.\n        if info.get_uri() != self.engine.uri:\n            return\n        self._duration_us = max(info.get_duration(), 0) // 1000\n        if not self.is_prepared():\n            self._seekable = bool(info.is_seekable())\n            self.stream_prepared(\n                bool(info.get_audio_streams()),\n                bool(info.get_video_streams()),\n                self._seekable, self._duration_us)\n\n    def _on_state_changed(self, _state):\n        pass\n\n    def _on_duration(self, duration):\n        self._duration_us = max(duration, 0) // 1000\n\n    def _on_position(self, position):\n        if self._seeking:\n            self._seek_done(position)\n        self.update(position // 1000)\n\n    def _on_seek_done(self, position):\n        self._seek_done(position)\n\n    def _seek_done(self, position):\n        if not self._seeking:\n            return\n        self._seeking = False\n        if self._seek_timeout:\n            GLib.source_remove(self._seek_timeout)\n            self._seek_timeout = 0\n        self.seek_success()\n        self.update(position // 1000)\n\n    def _on_seek_timeout(self):\n        self._seek_timeout = 0\n        if self._seeking:\n            self._seeking = False\n            self.seek_success()\n        return False\n\n    def _on_end_of_stream(self):\n        if self.get_loop():\n            self.engine.seek(0)\n            self.engine.start()\n            return\n        self._at_end = True\n        self.update(self._duration_us)\n        self.stream_ended()\n\n    def _on_error(self, error):\n        if not self._failed:\n            self._failed = True\n            self.gerror(error)\n\n    def _on_missing_plugin(self, description, detail):\n        if self._failed:\n            return\n        self._failed = True\n        self.gerror(GLib.Error.new_literal(\n            Gio.io_error_quark(),\n            missing_plugin_message(description, detail),\n            Gio.IOErrorEnum.NOT_SUPPORTED))\n\n    def _on_frame(self):\n        self.invalidate_contents()\n\n    def _on_size(self):\n        self.invalidate_size()\n\n    # Gtk.MediaStream vfuncs\n\n    def do_play(self):\n        if self.engine is None or self._failed:\n            return False\n        if self._at_end:\n            self._at_end = False\n            self.engine.seek(0)\n        self.engine.start()\n        return True\n\n    def do_pause(self):\n        if self.engine is not None:\n            self.engine.pause()\n\n    def do_seek(self, timestamp):\n        if self.engine is None:\n            return\n        if not self._seekable:\n            self.seek_failed()\n            return\n        self._at_end = False\n        self._seeking = True\n        self._seek_timeout = GLib.timeout_add(\n            SEEK_FALLBACK_MS, self._on_seek_timeout)\n        self.engine.seek(timestamp * 1000)\n\n    def do_update_audio(self, muted, volume):\n        if self.engine is not None:\n            self.engine.set_audio(muted, volume)\n\n    # Gdk.Paintable vfuncs: forwarded to the sink\'s paintable\n\n    def do_snapshot(self, snapshot, width, height):\n        if self.engine is not None and self.engine.paintable is not None:\n            self.engine.paintable.snapshot(snapshot, width, height)\n\n    def do_get_intrinsic_width(self):\n        if self.engine is None or self.engine.paintable is None:\n            return 0\n        return self.engine.paintable.get_intrinsic_width()\n\n    def do_get_intrinsic_height(self):\n        if self.engine is None or self.engine.paintable is None:\n            return 0\n        return self.engine.paintable.get_intrinsic_height()\n\n    def do_get_intrinsic_aspect_ratio(self):\n        if self.engine is None or self.engine.paintable is None:\n            return 0.0\n        return self.engine.paintable.get_intrinsic_aspect_ratio()\n'}
import sys, types, time, gc, weakref
import gi
gi.require_version('Gtk', '4.0'); gi.require_version('Adw', '1'); gi.require_version('Gst', '1.0')
from gi.repository import Gtk, Adw, GLib, Gst
pkg = types.ModuleType('pk'); pkg.__path__ = []; sys.modules['pk'] = pkg
i18n = types.ModuleType('pk.i18n'); i18n.gettext = lambda s: s; sys.modules['pk.i18n'] = i18n
for name, src in SOURCES.items():
    m = types.ModuleType('pk.' + name); m.__package__ = 'pk'; m.__file__ = name + '.py'
    sys.modules['pk.' + name] = m
    exec(compile(src, name + '.py', 'exec'), m.__dict__)
me = sys.modules['pk.mediaengine']; ms = sys.modules['pk.mediastream']
URL = 'https://mastodon.me.uk/system/media_attachments/files/117/581/332/107/689/033/original/13af5d8053337ede.mp4'
T0 = time.monotonic()
def log(m): print('%6.2fs %s' % (time.monotonic() - T0, m), flush=True)
res = {}
class App(Adw.Application):
    def __init__(s):
        super().__init__(application_id='x.Sandbox', flags=32)
    def do_activate(s):
        win = Adw.ApplicationWindow(application=s, default_width=800, default_height=600)
        video = Gtk.Video(); win.set_content(video); win.present()
        eng = me.Engine(); res['eng'] = weakref.ref(eng)
        stream = ms.EngineStream(eng)
        video.set_media_stream(stream)
        # first frame
        eng.paintable.connect('invalidate-contents', lambda *a: res.setdefault('frame', time.monotonic() - T0))
        eng.load(URL); stream.play()
        s.eng, s.stream, s.video = eng, stream, video
        GLib.timeout_add(100, s.poll)
        GLib.timeout_add(30000, s.fail)
    def sinks(s):
        out = []
        def walk(e):
            it = e.iterate_recurse()
            while True:
                r, x = it.next()
                if r == Gst.IteratorResult.OK:
                    out.append(x.get_factory().get_name() if x.get_factory() else x.get_name())
                elif r == Gst.IteratorResult.RESYNC:
                    it.resync()
                else:
                    break
        walk(s.eng.play.get_pipeline()); return out
    def poll(s):
        if 'frame' in res and 'seek' not in res:
            log('first frame at %.2fs prepared=%s dur_us=%s' % (res['frame'], s.stream.is_prepared(), s.stream.get_duration()))
            log('elements: ' + ','.join(sorted(set(s.sinks()))))
            res['seek'] = 0; s.stream.seek(10_000_000); s.t = time.monotonic()
            GLib.timeout_add(3000, s.after_seek)
        return 'done' not in res
    def after_seek(s):
        log('after seek ts_us=%s playing=%s error=%s' % (s.stream.get_timestamp(), s.stream.get_playing(), s.stream.get_error()))
        pipe = s.eng.play.get_pipeline()
        log('audio sinks: ' + ','.join(sorted(x for x in s.sinks() if 'sink' in x)))
        s.stream.detach(); s.video.set_media_stream(None)
        s.eng.release(); s.eng = None; s.stream = None
        GLib.timeout_add(1500, s.check_drop)
    def check_drop(s):
        gc.collect()
        log('engine dropped: %s  releasing=%d all=%d' % (res['eng']() is None, len(me._releasing), len(me._all)))
        res['done'] = 1; s.quit()
    def fail(s):
        log('TIMEOUT no result'); s.quit(); return False
App().run([])
me.shutdown_all(); log('exit clean')
